class Przycisk {
  constructor(etykieta) {
    this.etykieta = etykieta;
    this.wcisniety = 0;
    // BEZ bind, przekazanie this.onClick jako callback zgubiloby this
    this.onClick = this.onClick.bind(this);
  }
  onClick() {
    this.wcisniety++;
    console.log(`${this.etykieta}: klikniete ${this.wcisniety} razy`);
  }
}

const btn = new Przycisk("Zapisz");
const handler = btn.onClick; // wyrywamy metode
handler(); // "Zapisz: klikniete 1 razy" - dziala dzieki bind() w konstruktorze

class PrzyciskBezBind {
  constructor(etykieta) {
    this.etykieta = etykieta;
    this.wcisniety = 0;
    // BRAK bind() w konstruktorze
  }
  onClick() {
    this.wcisniety++; // rzuci blad, gdy this bedzie undefined
  }
}

const btn2 = new PrzyciskBezBind("Anuluj");
const handler2 = btn2.onClick;
// handler2(); -- Blad: Cannot read properties of undefined (reading 'wcisniety')

class PrzyciskArrow {
  wcisniety = 0;
  etykieta;
  constructor(etykieta) {
    this.etykieta = etykieta;
  }
  // arrow function jako pole klasy - this AUTOMATYCZNIE == instancja
  onClick = () => {
    this.wcisniety++;
    console.log(`${this.etykieta}: klikniete ${this.wcisniety} razy`);
  };
}

const btn3 = new PrzyciskArrow("Wyslij");
const handler3 = btn3.onClick; // wyrywamy metode
handler3(); // "Wyslij: klikniete 1 razy" - dziala BEZ recznego bind() w konstruktorze!

class Licznik {
  wartosc = 0;
  zwieksz() {
    this.wartosc++;
  }
}

const licznik = new Licznik();
licznik.zwieksz(); // OK - dziala poprawnie, this === licznik

// ale:
setTimeout(licznik.zwieksz, 100); // BLAD - this bedzie undefined w setTimeout

class Licznik {
  wartosc = 0;
  constructor() {
    this.zwieksz = this.zwieksz.bind(this);
  }
  zwieksz() {
    this.wartosc++;
  }
}

const licznik = new Licznik();
setTimeout(licznik.zwieksz, 100); // POPRAWNIE - this pozostaje licznik dzieki bind()

