class Zegarek {
  constructor(marka) {
    this.marka = marka;
    this.tykniecia = 0;
    this.tyknij = this.tyknij.bind(this);
  }
  tyknij() {
    this.tykniecia++;
  }
}

const zegarek = new Zegarek("Casio");
const wyciagniete = zegarek.tyknij;
wyciagniete();
console.log(zegarek.tykniecia); // 1

class Suwak {
  wartosc = 0;
  zmien = (o) => {
    this.wartosc += o;
  };
}

const suwak = new Suwak();
const wyciagniete = suwak.zmien;
wyciagniete(5);
console.log(suwak.wartosc); // 5 - dziala mimo wyrwania, bo zmien to arrow function

class PrzyciskEmail {
  wyslane = 0;
  wyslij() {
    this.wyslane++;
  }
}

const przycisk = new PrzyciskEmail();
const wyciagniete = przycisk.wyslij;
// wyciagniete(); -- Blad: Cannot read properties of undefined (reading 'wyslane')
// this jest undefined, bo metoda zostala wyciagnieta bez zadnego
// zabezpieczenia (ani bind() w konstruktorze, ani arrow function jako pole).

class PrzyciskEmailNaprawiony {
  wyslane = 0;
  constructor() {
    this.wyslij = this.wyslij.bind(this);
  }
  wyslij() {
    this.wyslane++;
  }
}

const przycisk = new PrzyciskEmailNaprawiony();
const wyciagniete = przycisk.wyslij;
wyciagniete(); // dziala poprawnie dzieki bind() w konstruktorze
console.log(przycisk.wyslane); // 1

class Formularz {
  bledy = [];
  dodajBlad(tekst) {
    this.bledy.push(tekst);
  }
}

const formularz = new Formularz();
// setTimeout(formularz.dodajBlad, 10, "blad");
// Po 10ms wystapilby blad: Cannot read properties of undefined (reading 'push')
// this jest undefined, bo setTimeout wywoluje przekazana metode samodzielnie,
// bez zadnego powiazania z instancja formularz - metoda nie zostala
// zabezpieczona ani przez bind(), ani przez arrow function jako pole klasy.

class FormularzArrow {
  bledy = [];
  dodajBlad = (tekst) => {
    this.bledy.push(tekst);
  };
}

const formularz = new FormularzArrow();
setTimeout(formularz.dodajBlad, 10, "blad walidacji");

setTimeout(() => {
  console.log(formularz.bledy); // ["blad walidacji"] - dziala poprawnie po 10ms
}, 20);

class Zakladka {
  constructor(nazwa) {
    this.nazwa = nazwa;
    this.aktywna = false;
    this.aktywuj = this.aktywuj.bind(this);
    this.dezaktywuj = this.dezaktywuj.bind(this);
  }
  aktywuj() {
    this.aktywna = true;
  }
  dezaktywuj() {
    this.aktywna = false;
  }
}

const zakladka = new Zakladka("Ustawienia");
const wyciagnietyAktywuj = zakladka.aktywuj;
wyciagnietyAktywuj(); // dziala dzieki bind()
console.log(zakladka.aktywna); // true

// Klasy w JavaScript sa, pod wzgledem this, rzadzone DOKLADNIE tymi samymi
// zasadami co zwykle obiekty - metoda klasy wywolana instancja.metoda()
// ma this === instancja, ale wyciagnieta (przypisana do zmiennej, przekazana
// jako callback) traci to powiazanie - to IDENTYCZNY problem co w lekcji 2.
//
// bind(this) w konstruktorze dziala z tego samego powodu co kazde inne
// uzycie bind() (lekcja 6) - tworzy NOWA funkcje z na stale przypietym this,
// niezaleznie od pozniejszego sposobu wywolania.
//
// Arrow function jako pole klasy dziala z tego samego powodu co arrow
// function jako callback (lekcja 3) - arrow function NIE MA wlasnego this,
// wiec dziedziczy je z otaczajacego zasiegu, ktorym w przypadku pola klasy
// jest KONSTRUKTOR (a wiec this === tworzona instancja), i to powiazanie
// pozostaje trwale, niezaleznie od tego, gdzie metoda zostanie pozniej uzyta.
